# Embedded binary asset for drawing hand
import base64
from pathlib import Path

HAND_PNG_B64 = """"""

def ensure_drawing_hand(target: Path):
    if not target.exists() or target.stat().st_size < 1000:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(base64.b64decode(HAND_PNG_B64))
